import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.D7WGirly.js";const m=JSON.parse('{"title":"Settings — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"settings-04-troubleshooting-and-faqs.md","filePath":"settings-04-troubleshooting-and-faqs.md"}'),i={name:"settings-04-troubleshooting-and-faqs.md"};function r(o,e,h,l,d,c){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="settings-—-troubleshooting-faqs" tabindex="-1">Settings — Troubleshooting &amp; FAQs <a class="header-anchor" href="#settings-—-troubleshooting-faqs" aria-label="Permalink to &quot;Settings — Troubleshooting &amp; FAQs&quot;">​</a></h1><p><em>Common configuration issues and answers to frequent questions</em></p><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="who-can-access-settings" tabindex="-1">Who can access Settings? <a class="header-anchor" href="#who-can-access-settings" aria-label="Permalink to &quot;Who can access Settings?&quot;">​</a></h3><p>Both Admins and Builders can access Settings, but they have different permissions. Builders cannot update the organization name, description, or logo; assign or change member roles; or connect the Gong integration. Admins can do everything.</p><h3 id="what-s-the-difference-between-admin-and-builder" tabindex="-1">What&#39;s the difference between Admin and Builder? <a class="header-anchor" href="#what-s-the-difference-between-admin-and-builder" aria-label="Permalink to &quot;What&#39;s the difference between Admin and Builder?&quot;">​</a></h3><p>Admins have full access to all platform features and Settings. Builders have full access to all planning modules (Features, Roadmaps, Releases, Strategy, Documents, Auctions, Extracts) but cannot change organization-level identity, manage roles, or connect Gong.</p><h3 id="can-i-change-a-member-s-role-after-they-ve-joined" tabindex="-1">Can I change a member&#39;s role after they&#39;ve joined? <a class="header-anchor" href="#can-i-change-a-member-s-role-after-they-ve-joined" aria-label="Permalink to &quot;Can I change a member&#39;s role after they&#39;ve joined?&quot;">​</a></h3><p>Yes. Admins can change any member&#39;s role at any time from Settings &gt; Team. Changes take effect immediately.</p><h3 id="is-there-always-at-least-one-admin-required" tabindex="-1">Is there always at least one Admin required? <a class="header-anchor" href="#is-there-always-at-least-one-admin-required" aria-label="Permalink to &quot;Is there always at least one Admin required?&quot;">​</a></h3><p>Yes. Lodestone enforces a minimum of one Admin per workspace. You cannot remove or demote the last Admin.</p><h3 id="what-happens-when-an-organization-is-archived" tabindex="-1">What happens when an organization is archived? <a class="header-anchor" href="#what-happens-when-an-organization-is-archived" aria-label="Permalink to &quot;What happens when an organization is archived?&quot;">​</a></h3><p>Builders immediately lose access to the workspace. Admins retain access and can unarchive at any time from Settings &gt; Organization, which immediately restores Builder access.</p><h3 id="are-settings-changes-global-or-per-user" tabindex="-1">Are Settings changes global or per-user? <a class="header-anchor" href="#are-settings-changes-global-or-per-user" aria-label="Permalink to &quot;Are Settings changes global or per-user?&quot;">​</a></h3><p>Global. All Settings apply across the entire workspace. There are no per-user overrides for status stages, evaluation criteria, organization description, or other configuration.</p><h3 id="what-happens-to-features-when-i-delete-a-status-stage" tabindex="-1">What happens to Features when I delete a status stage? <a class="header-anchor" href="#what-happens-to-features-when-i-delete-a-status-stage" aria-label="Permalink to &quot;What happens to Features when I delete a status stage?&quot;">​</a></h3><p>Features currently in the deleted stage are automatically moved to the default stage. Review which Features are in the stage before deleting to avoid unexpected status changes across your backlog and Release boards.</p><h3 id="can-i-have-more-than-one-evaluation-framework-active-at-the-same-time" tabindex="-1">Can I have more than one evaluation framework active at the same time? <a class="header-anchor" href="#can-i-have-more-than-one-evaluation-framework-active-at-the-same-time" aria-label="Permalink to &quot;Can I have more than one evaluation framework active at the same time?&quot;">​</a></h3><p>No. Only one evaluation framework is active at a time. Switching frameworks changes which fields are displayed — previously entered scores for the inactive framework are preserved and reappear if you switch back.</p><h3 id="is-the-strategy-default-setting-a-hard-constraint-or-just-a-preference" tabindex="-1">Is the Strategy Default setting a hard constraint or just a preference? <a class="header-anchor" href="#is-the-strategy-default-setting-a-hard-constraint-or-just-a-preference" aria-label="Permalink to &quot;Is the Strategy Default setting a hard constraint or just a preference?&quot;">​</a></h3><p>It&#39;s a default, not a constraint. The workspace default pre-selects an approach when creating a new Strategy, but it can be overridden at the point of creation. Each Strategy keeps its own approach regardless of what the default is set to.</p><h3 id="can-builders-invite-new-team-members" tabindex="-1">Can Builders invite new team members? <a class="header-anchor" href="#can-builders-invite-new-team-members" aria-label="Permalink to &quot;Can Builders invite new team members?&quot;">​</a></h3><p>Yes. Any member can invite new members. However, only Admins can assign or change roles — Builders cannot promote someone to Admin or demote an Admin to Builder.</p><h3 id="who-can-create-and-delete-object-types-in-taxonomy" tabindex="-1">Who can create and delete object types in Taxonomy? <a class="header-anchor" href="#who-can-create-and-delete-object-types-in-taxonomy" aria-label="Permalink to &quot;Who can create and delete object types in Taxonomy?&quot;">​</a></h3><p>Only Admins can create, rename, or delete object types in Settings &gt; Taxonomy. All members can assign types to items and change an item&#39;s type from the Backlog.</p><h3 id="can-i-rename-an-object-type-prefix-after-items-have-been-assigned-to-it" tabindex="-1">Can I rename an object type prefix after items have been assigned to it? <a class="header-anchor" href="#can-i-rename-an-object-type-prefix-after-items-have-been-assigned-to-it" aria-label="Permalink to &quot;Can I rename an object type prefix after items have been assigned to it?&quot;">​</a></h3><p>No. Prefixes are locked once items have been assigned to the type, because changing the prefix would alter existing typed IDs (e.g. FEAT-001 → NEWFEAT-001). Typed IDs are designed to be stable references. If you need a different prefix, create a new type with the correct prefix and reassign items to it.</p><h3 id="what-happens-to-items-when-i-delete-an-object-type" tabindex="-1">What happens to items when I delete an object type? <a class="header-anchor" href="#what-happens-to-items-when-i-delete-an-object-type" aria-label="Permalink to &quot;What happens to items when I delete an object type?&quot;">​</a></h3><p>You must reassign all items currently using the type before deletion is allowed. The delete dialog shows the count of affected items and asks you to select a replacement type. Items are moved to the replacement type, and the original type is then removed.</p><h3 id="can-passkeys-replace-my-password" tabindex="-1">Can passkeys replace my password? <a class="header-anchor" href="#can-passkeys-replace-my-password" aria-label="Permalink to &quot;Can passkeys replace my password?&quot;">​</a></h3><p>Passkeys are an additional sign-in option, not a replacement. Your password remains active. You can sign in with either method — use whichever is more convenient for your device and context.</p><h3 id="can-i-set-up-a-passkey-on-multiple-devices" tabindex="-1">Can I set up a passkey on multiple devices? <a class="header-anchor" href="#can-i-set-up-a-passkey-on-multiple-devices" aria-label="Permalink to &quot;Can I set up a passkey on multiple devices?&quot;">​</a></h3><p>Yes. You can register as many passkeys as you like from Account &gt; Passkeys — one per device is the typical pattern. Each passkey is specific to the device it was created on.</p><hr><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="ai-generated-documents-feel-generic-and-off-brand" tabindex="-1">AI-generated Documents feel generic and off-brand <a class="header-anchor" href="#ai-generated-documents-feel-generic-and-off-brand" aria-label="Permalink to &quot;AI-generated Documents feel generic and off-brand&quot;">​</a></h3><p>The most common cause is a missing or vague Organization Description. Go to Settings &gt; Organization and update it with specific details about your industry, business model, customer profile, and product positioning. See the Advanced section for guidance on what to include.</p><h3 id="a-team-member-can-t-access-certain-settings-options" tabindex="-1">A team member can&#39;t access certain Settings options <a class="header-anchor" href="#a-team-member-can-t-access-certain-settings-options" aria-label="Permalink to &quot;A team member can&#39;t access certain Settings options&quot;">​</a></h3><p>Check their role. In Settings, Builder restrictions are visually enforced — unavailable fields and sections appear greyed out and non-interactive, and an Admin-required notice is displayed. Builders cannot change the organization name, description, or logo; assign roles; or connect Gong. The Features sub-tab under Settings &gt; Modules is hidden entirely for Builders.</p><p>If the team member needs these capabilities, an Admin can promote them to Admin from Settings &gt; Team.</p><h3 id="features-have-moved-to-the-wrong-status-after-a-settings-change" tabindex="-1">Features have moved to the wrong status after a Settings change <a class="header-anchor" href="#features-have-moved-to-the-wrong-status-after-a-settings-change" aria-label="Permalink to &quot;Features have moved to the wrong status after a Settings change&quot;">​</a></h3><p>This happens when a status stage is deleted — Features in that stage are automatically moved to the default stage. If this caused unexpected changes, manually update the affected Features to the correct stage. Going forward, review which Features are in a stage before deleting it.</p><h3 id="the-evaluation-scores-have-disappeared-from-the-feature-backlog" tabindex="-1">The evaluation scores have disappeared from the Feature backlog <a class="header-anchor" href="#the-evaluation-scores-have-disappeared-from-the-feature-backlog" aria-label="Permalink to &quot;The evaluation scores have disappeared from the Feature backlog&quot;">​</a></h3><p>You&#39;ve likely switched evaluation frameworks. Previously entered scores aren&#39;t deleted — they&#39;re preserved for the inactive framework. Switch back to the previous framework in Settings &gt; Modules &gt; Feature Evaluation Criteria to restore visibility of those scores.</p><h3 id="i-can-t-remove-the-last-admin-from-the-workspace" tabindex="-1">I can&#39;t remove the last Admin from the workspace <a class="header-anchor" href="#i-can-t-remove-the-last-admin-from-the-workspace" aria-label="Permalink to &quot;I can&#39;t remove the last Admin from the workspace&quot;">​</a></h3><p>This is a safeguard — there must always be at least one Admin. To remove the current Admin, first promote another member to Admin, then remove or demote the original.</p><h3 id="a-builder-is-trying-to-create-or-delete-an-object-type-in-taxonomy-but-can-t" tabindex="-1">A Builder is trying to create or delete an object type in Taxonomy but can&#39;t <a class="header-anchor" href="#a-builder-is-trying-to-create-or-delete-an-object-type-in-taxonomy-but-can-t" aria-label="Permalink to &quot;A Builder is trying to create or delete an object type in Taxonomy but can&#39;t&quot;">​</a></h3><p>Creating, renaming, and deleting object types in Settings &gt; Taxonomy is restricted to Admins. Builders can assign types to items and change an item&#39;s type from the Backlog, but they cannot modify the type list itself. Have an Admin make the change from Settings &gt; Taxonomy.</p><h3 id="a-builder-is-trying-to-connect-the-gong-integration-but-can-t" tabindex="-1">A Builder is trying to connect the Gong integration but can&#39;t <a class="header-anchor" href="#a-builder-is-trying-to-connect-the-gong-integration-but-can-t" aria-label="Permalink to &quot;A Builder is trying to connect the Gong integration but can&#39;t&quot;">​</a></h3><p>Connecting Gong is restricted to Admins. Have an Admin connect the integration from Settings &gt; Integrations. Once connected, Builders can use the Gong import in the Extracts module.</p><h3 id="the-organization-has-been-archived-and-builders-have-lost-access" tabindex="-1">The Organization has been archived and Builders have lost access <a class="header-anchor" href="#the-organization-has-been-archived-and-builders-have-lost-access" aria-label="Permalink to &quot;The Organization has been archived and Builders have lost access&quot;">​</a></h3><p>An Admin needs to log in and unarchive from Settings &gt; Organization. Builder access is restored immediately upon unarchiving.</p><hr><h2 id="trial-subscription-questions" tabindex="-1">Trial &amp; Subscription Questions <a class="header-anchor" href="#trial-subscription-questions" aria-label="Permalink to &quot;Trial &amp; Subscription Questions&quot;">​</a></h2><h3 id="how-long-is-the-free-trial" tabindex="-1">How long is the free trial? <a class="header-anchor" href="#how-long-is-the-free-trial" aria-label="Permalink to &quot;How long is the free trial?&quot;">​</a></h3><p>Lodestone trials last 31 days from the date you sign up.</p><h3 id="where-can-i-see-how-many-days-are-left-in-my-trial" tabindex="-1">Where can I see how many days are left in my trial? <a class="header-anchor" href="#where-can-i-see-how-many-days-are-left-in-my-trial" aria-label="Permalink to &quot;Where can I see how many days are left in my trial?&quot;">​</a></h3><p>The sidebar shows a <strong>Trial account</strong> card with a live countdown and a progress bar. The count is calculated from the exact moment your trial expires, not your sign-up date, so it is always accurate to the day.</p><h3 id="what-happens-when-the-trial-expires" tabindex="-1">What happens when the trial expires? <a class="header-anchor" href="#what-happens-when-the-trial-expires" aria-label="Permalink to &quot;What happens when the trial expires?&quot;">​</a></h3><p>If your trial expires without an active subscription, the app content blurs and a paywall appears. You can still access the upgrade flow and enter an access code from the paywall overlay. Your data is not deleted.</p><h3 id="can-i-still-access-lodestone-if-my-trial-has-ended" tabindex="-1">Can I still access Lodestone if my trial has ended? <a class="header-anchor" href="#can-i-still-access-lodestone-if-my-trial-has-ended" aria-label="Permalink to &quot;Can I still access Lodestone if my trial has ended?&quot;">​</a></h3><p>Only through the paywall — you can upgrade to a paid plan or apply an access code from that screen. Once payment is confirmed or a valid code is applied, full access is restored immediately.</p><h3 id="what-does-an-access-code-do" tabindex="-1">What does an access code do? <a class="header-anchor" href="#what-does-an-access-code-do" aria-label="Permalink to &quot;What does an access code do?&quot;">​</a></h3><p>An access code extends your trial by a specified number of days from the time you apply it. If your trial has not yet expired, the extension starts from the current expiry date. If your trial has already expired, the extension starts from today.</p><hr><h2 id="common-trial-issues" tabindex="-1">Common Trial Issues <a class="header-anchor" href="#common-trial-issues" aria-label="Permalink to &quot;Common Trial Issues&quot;">​</a></h2><h3 id="the-sidebar-shows-the-wrong-number-of-days-left" tabindex="-1">The sidebar shows the wrong number of days left <a class="header-anchor" href="#the-sidebar-shows-the-wrong-number-of-days-left" aria-label="Permalink to &quot;The sidebar shows the wrong number of days left&quot;">​</a></h3><p>If the days-left count looks wrong, try a hard refresh (Cmd+Shift+R or Ctrl+Shift+R). The countdown is calculated server-side from your trial expiry date each time the page loads — it cannot drift or show stale data unless the page hasn&#39;t been refreshed.</p><h3 id="my-trial-should-be-active-but-the-paywall-appeared" tabindex="-1">My trial should be active but the paywall appeared <a class="header-anchor" href="#my-trial-should-be-active-but-the-paywall-appeared" aria-label="Permalink to &quot;My trial should be active but the paywall appeared&quot;">​</a></h3><p>Check whether your trial expiry date has passed. The paywall appears as soon as the trial expires with no active subscription. If you believe this is an error, contact support with your account email — an access code can extend your access immediately while the issue is investigated.</p><h3 id="i-applied-an-access-code-but-the-paywall-is-still-showing" tabindex="-1">I applied an access code but the paywall is still showing <a class="header-anchor" href="#i-applied-an-access-code-but-the-paywall-is-still-showing" aria-label="Permalink to &quot;I applied an access code but the paywall is still showing&quot;">​</a></h3><p>After applying a code, the page redirects to your account page with a confirmation. If the paywall reappears after navigating away, try signing out and back in to refresh your session. If the issue persists, contact support — the code may not have been applied correctly.</p><p><em>This is version 1 of the Settings documentation, based on the Lodestone knowledge base from early 2025, updated with confirmed platform behavior.</em></p>',74)])])}const p=a(i,[["render",r]]);export{m as __pageData,p as default};
